"""F. Risk Recommendations generated by the backend decision engine."""

import api_client as api
import pandas as pd
import streamlit as st
from components import (
    RISK,
    header,
    note,
    perf_badge,
    risk_cell,
    safe,
    synthetic_notice,
    table,
)

from sections.shared import select_analysis


def render() -> None:
    header(
        "Risk Recommendations & Governance",
        "Executive credit risk committee directives generated by the policy decision engine",
    )
    choice = select_analysis("rec_job")
    if not choice:
        return
    rec = safe(lambda: api.get(f"/recommendations/{choice['job_id']}"))
    if not rec:
        return
    synthetic_notice(rec.get("is_synthetic"))

    fg, bg = RISK.get(rec["risk_category"], ("#1E3A8A", "#EFF6FF"))
    risk_cat = rec["risk_category"]
    risk_symbol = {
        "LOW RISK": "🟢",
        "MEDIUM RISK": "🟡",
        "HIGH RISK": "🟠",
        "CRITICAL RISK": "🔴",
    }.get(risk_cat, "⚪")

    st.markdown(
        f"""
        <div class="dg-risk" style="background:{bg}; color:{fg}; border:1.5px solid {fg}44;">
            <div style="display:flex; justify-content:space-between; align-items:center;">
                <div class="lbl">Governance Assessment · {rec['batch_name']}</div>
                <span style="background:{fg}; color:#fff; font-size:0.75rem; font-weight:700; padding:3px 10px; border-radius:9999px;">
                    ALERT: {rec['alert_type'] or 'STANDARD MONITORING'}
                </span>
            </div>
            <div class="val">{risk_symbol} {risk_cat}</div>
            <div style="font-size:0.95rem; opacity:0.92; margin-top:4px;">
                Drift Level: <b>{rec['drift_level'].upper()}</b> &nbsp;·&nbsp;
                Overall DIS: <b>{rec['overall_dis']:.3f}</b> &nbsp;·&nbsp;
                Model State: <b>{rec['performance_state'].upper()}</b>
            </div>
        </div>
        """,
        unsafe_allow_html=True,
    )

    left, right = st.columns([3, 2])
    with left:
        st.markdown("#### 📋 Recommended Committee Actions")
        for i, a in enumerate(rec["recommended_actions"], 1):
            st.markdown(
                f"""
                <div style="background:#FFFFFF; border:1px solid #E2E8F0; border-left:4px solid {fg}; border-radius:8px; padding:12px 16px; margin-bottom:8px; box-shadow:0 1px 2px rgba(0,0,0,0.03);">
                    <b>Action {i}:</b> {a}
                </div>
                """,
                unsafe_allow_html=True,
            )

        st.markdown("#### 🔍 Underlying Evidence")
        for e in rec["evidence"]:
            st.markdown(f"- `{e}`")

    with right:
        st.markdown("#### 🩺 Model Performance Surveillance")
        st.markdown(perf_badge(rec["performance_state"]), unsafe_allow_html=True)
        st.write(rec["model_health_message"])

        st.markdown("#### 🤖 Decision Engine Logic")
        st.info(rec["recommendation"])

        if rec["affected_features"]:
            st.markdown("#### ⚠️ Distorted Credit Attributes")
            tags = " ".join(
                [
                    f"<span style='background:#F1F5F9; border:1px solid #CBD5E1; color:#0F172A; padding:3px 8px; border-radius:6px; font-size:0.8rem; font-weight:600; display:inline-block; margin:2px;'>{feat}</span>"
                    for feat in rec["affected_features"]
                ]
            )
            st.markdown(tags, unsafe_allow_html=True)

    st.markdown("<div style='height:12px'></div>", unsafe_allow_html=True)
    note(
        "<b>Governance Principle:</b> DriftGuard never retrains credit models or alters loan sanctioning rules automatically. "
        "A CRITICAL designation requires empirically confirmed default degradation; input drift alone caps at HIGH."
    )

    hist = safe(lambda: api.get("/analysis/history"), {}) or {}
    latest = hist.get("latest_per_batch", [])
    if latest:
        st.markdown("#### 📊 Portfolio Historical Risk Posture")
        df = pd.DataFrame(
            [
                {
                    "Batch": r["batch_id"],
                    "Date": r["batch_date"],
                    "Overall DIS": r["overall_dis"],
                    "Risk Category": r["risk_category"],
                    "Alert Flag": r["alert_type"] or "none",
                    "Model Health": r["performance_state"].title(),
                    "Top Driving Attributes": ", ".join(r["top_features"]),
                }
                for r in latest
            ]
        )
        table(df, {"Overall DIS": ".3f"}, {"Risk Category": risk_cell})
